package e.e.a;
import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,34,36},manifest=Config.NONE)
public class NicoliveAuditTest {
 NicoliveSession session;ServiceController<NicoliveService> sc;NicoliveService s;
 @Before public void setup(){session=new NicoliveSession("lv123","",new NicoliveSession.Listener(){public void program(NicoliveData.Program p){}public void stream(JSONObject p){}public void status(String p,boolean e){}public void comment(NicoliveData.Chat c){}public void commentState(boolean b){}public void posted(boolean b,String p){}});sc=Robolectric.buildService(NicoliveService.class);s=sc.create().get();}
 @After public void close()throws Exception{session.close();session.closeTask.get(5,TimeUnit.SECONDS);sc.destroy();}
 @Test public void pendingPostReleasedOnTransportCancellation(){session.posting=true;session.postTimeout=session.timers.schedule(()->{},10,TimeUnit.SECONDS);ScheduledFuture<?> timer=session.postTimeout;session.cancelTransport(false);assertFalse(session.posting);assertTrue(timer.isCancelled());}
 CountDownLatch blockWorkers()throws Exception{CountDownLatch entered=new CountDownLatch(3),release=new CountDownLatch(1);for(int i=0;i<3;i++)session.workers.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(entered.await(5,TimeUnit.SECONDS));return release;}
 @Test public void duplicateCommentServersQueueOneReader()throws Exception{CountDownLatch release=blockWorkers();try{JSONObject m=new JSONObject().put("type","messageServer").put("data",new JSONObject().put("viewUri","https://mpn.live.nicovideo.jp/view/test"));for(int i=0;i<100;i++)session.message(null,m,session.generation);assertEquals(1,((ThreadPoolExecutor)session.workers).getQueue().size());}finally{session.close();release.countDown();}}
 @Test public void burstReconnectsQueueOnlyLatestWatch()throws Exception{CountDownLatch release=blockWorkers();try{for(int i=0;i<200;i++)session.reconnect();assertEquals(1,((ThreadPoolExecutor)session.workers).getQueue().size());}finally{session.close();release.countDown();}}
 @Test public void detachReleasesCommentServiceReference(){NicolivePlayerFrame first=new NicolivePlayerFrame(s,false),next=new NicolivePlayerFrame(s,false);s.attach(first);s.attach(next);assertNull(first.comments.service);s.detach(next);assertNull(next.comments.service);}
 @Test public void streamReplacementHonorsPauseAndCookieOwnership()throws Exception{
  androidx.media3.exoplayer.ExoPlayer actual=s.player;final boolean[] requested={false};final int[] prepared={0};
  s.player=(androidx.media3.exoplayer.ExoPlayer)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{androidx.media3.exoplayer.ExoPlayer.class},(p,m,a)->{String n=m.getName();if(n.equals("setPlayWhenReady")){requested[0]=(Boolean)a[0];return null;}if(n.equals("prepare")){prepared[0]++;return null;}if(n.equals("setMediaSource")||n.equals("pause"))return null;if(n.equals("getPlayWhenReady"))return requested[0];if(n.equals("play")){requested[0]=true;return null;}return m.invoke(actual,a);});
  try{JSONArray first=new JSONArray().put(new JSONObject().put("name","test").put("value","old"));s.applyStream(new JSONObject().put("uri","https://delivery.live.nicovideo.jp/test.m3u8").put("cookies",first));assertTrue(requested[0]);NicoliveService.CookieSource old=s.new CookieSource(s.mediaCookies);s.pause();s.applyStream(new JSONObject().put("uri","https://delivery.live.nicovideo.jp/quality.m3u8").put("cookies",new JSONArray()));assertFalse(requested[0]);assertEquals(2,prepared[0]);assertSame(first,old.cookies);assertNotSame(old.cookies,s.mediaCookies);s.resume();assertTrue(requested[0]);}finally{s.player=actual;}
 }
 @Test public void oneHourQueueSimulationStaysBounded(){NicoliveServiceTest.PlayingService live=new NicoliveServiceTest.PlayingService();live.ng=new NicoliveNg(s);live.program=new NicoliveData.Program("lv123");for(int minute=0;minute<60;minute++){for(int j=0;j<2000;j++){NicoliveData.Chat c=new NicoliveData.Chat();c.text="load";c.vpos=live.epoch/10;live.incoming.add(c);}live.tick.run();live.main.removeCallbacks(live.tick);assertTrue(live.history.size()<=2000);assertTrue(live.scheduled.size()<=2000);assertTrue(live.incoming.isEmpty());live.epoch+=60000;}assertEquals(120000,live.deliveredCount);}
}
